messages.content:
Game edukasi Endless Runner tentang sistem organ tubuh manusia dengan tema Cartoon dan kesulitan Normal. Asumsi: item organ muncul acak di jalur dan target sistem berganti setiap 5 item benar.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "body-runner-sistem-organ", title: "Body Runner: Sistem Organ", seed: "body-runner-01",
  theme: { preset: "cartoon" },

  learning: {
    subject: "Biologi",
    concept: "Mengelompokkan organ tubuh manusia berdasarkan sistem pencernaan, pernapasan, dan peredaran darah",
    objectives: [
      "Mengidentifikasi organ sesuai sistemnya",
      "Memahami keterkaitan jantung dan paru-paru dalam peredaran darah"
    ],
    misconceptions: [
      "Jantung hanya memompa darah dan tidak berhubungan dengan paru-paru"
    ],
    mode: "category",
    categories: [
      { id: "pencernaan", label: "Pencernaan", color: "#3FA34D" },
      { id: "pernapasan", label: "Pernapasan", color: "#2F80ED" },
      { id: "peredaran",  label: "Peredaran Darah", color: "#E5484D" }
    ],
    items: [
      { id: "lambung",      label: "Lambung",      category: "pencernaan", explain: "Mencerna makanan secara mekanik dan kimia." },
      { id: "usus-halus",   label: "Usus halus",   category: "pencernaan", explain: "Menyerap sari-sari makanan hasil pencernaan." },
      { id: "kerongkongan", label: "Kerongkongan", category: "pencernaan", explain: "Menyalurkan makanan dari mulut ke lambung." },
      { id: "paru-paru",    label: "Paru-paru",    category: "pernapasan", explain: "Tempat pertukaran oksigen dan karbon dioksida." },
      { id: "trakea",       label: "Trakea",       category: "pernapasan", explain: "Saluran udara dari tenggorokan menuju paru-paru." },
      { id: "diafragma",    label: "Diafragma",    category: "pernapasan", explain: "Otot yang membantu proses pernapasan." },
      { id: "jantung",      label: "Jantung",      category: "peredaran",  explain: "Memompa darah; bekerja bersama paru-paru dalam peredaran pulmonal." },
      { id: "arteri",       label: "Arteri",       category: "peredaran",  explain: "Pembuluh yang membawa darah keluar dari jantung." },
      { id: "vena",         label: "Vena",         category: "peredaran",  explain: "Pembuluh yang membawa darah kembali ke jantung." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "kuman", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "batu",  w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
